    (v_ws, 'asistente-publico', 'pol.parqueadero', 'guia', 'con_herramienta', null, 'Sabor no tiene parqueadero. Al frente hay una bahía sin vigilancia, de la que Sabor no responde, y hay un parqueadero a unas cuadras.', '{}'::text[], null, '[KICKOFF 22-oct] kickoff-ideas-y-pendientes §1; diseño §8.5 (texto por confirmar con Paula)', null),
    (v_ws, 'asistente-publico', 'pol.llegada', 'guia', 'con_herramienta', null, '[EJEMPLO] Llega 20 minutos antes. La experiencia empieza a la hora; si llegas tarde te unes en el tiempo en curso.', '{}'::text[], null, '[EJEMPLO] HUECO §12.3: políticas escritas de Sabor', null),
    (v_ws, 'asistente-publico', 'pol.ninos', 'guia', 'con_herramienta', null, 'Depende de la experiencia: en unas no entran menores de edad y en otras entran niños desde cierta edad (la edad de cada experiencia está en su ficha). Los menores de 6 años no entran a ninguna.', '{}'::text[], null, '[KICKOFF 22-oct] kickoff-ideas-y-pendientes §1; diseño §8.5 (texto por confirmar con Paula)', null),
